#!/usr/bin/env node
// Compiles the wet-media kernel (assembly/wet.ts) with AssemblyScript into two WebAssembly SIMD
// modules, one for shared memory (Web Workers) and one for ordinary memory (a single thread), and
// writes them base64-encoded into src/paint/wet/kernel-wasm.ts, which the engine imports lazily.
// The generated file is committed, so building the package needs no AssemblyScript;
// tests/paint-wet-kernel.test.ts checks it is up to date with the source.
//
//   pnpm --filter @pixerate/editor build:wasm
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = path.join(root, 'assembly/wet.ts');
const out = path.join(root, 'src/paint/wet/kernel-wasm.ts');

/** The asc flags of each variant (exported so the test can rebuild and compare). */
export const VARIANTS = {
  shared: ['--enable', 'simd', '--enable', 'threads', '--importMemory', '--sharedMemory', '--initialMemory', '1', '--maximumMemory', '65536'],
  single: ['--enable', 'simd', '--importMemory', '--initialMemory', '1'],
};
const COMMON = ['-O3', '--runtime', 'stub', '--noAssert', '--memoryBase', '0'];

export function sourceHash() {
  return createHash('sha256').update(readFileSync(source)).digest('hex').slice(0, 16);
}

export function compile(flags) {
  const dir = mkdtempSync(path.join(tmpdir(), 'wet-wasm-'));
  try {
    const file = path.join(dir, 'wet.wasm');
    const asc = path.join(root, 'node_modules/.bin/asc');
    execFileSync(asc, [source, '-o', file, ...COMMON, ...flags], { stdio: 'inherit' });
    return readFileSync(file);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

export function generate() {
  const shared = compile(VARIANTS.shared);
  const single = compile(VARIANTS.single);
  return `// Generated by scripts/build-wet-wasm.mjs from assembly/wet.ts. Do not edit; run \`pnpm build:wasm\`.
/* eslint-disable */

/** sha256 (first 16 hex digits) of assembly/wet.ts when this file was generated. */
export const WET_KERNEL_SOURCE_HASH = '${sourceHash()}';

/** The kernel for shared memory (Web Workers), ${shared.length} bytes. */
export const WET_KERNEL_SHARED = '${shared.toString('base64')}';

/** The kernel for ordinary memory (one thread), ${single.length} bytes. */
export const WET_KERNEL_SINGLE = '${single.toString('base64')}';
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(out, generate());
  console.log(`wrote ${path.relative(root, out)}`);
}
